int smb2_handle_write_op(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    struct TCP_Server_Info *server = io_parms->tcon->ses->server;

    if (!server || !serverCanDialectBeSMB2(server->dialect)) {
        return -EOPNOTSUPP;
    }

    req = cifs_small_tcon_alloc_mid(server);
    if (!req)
        return -ENOMEM;

    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->WriteChannelInfoOffset = 0;
    req->WriteChannelInfoLength = 0;
    req->DataOffset = cpu_to_le16(offsetof(struct smb2_write_request, Buffer));
    req->DataLength = cpu_to_le32(io_parms->offset);

    resp = cifs_send_recv(xid, server, (char *)req, iov, n_vec, &resp_buf_type, 0);
    if (IS_ERR(resp)) {
        rc = PTR_ERR(resp);
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
out:
    cifs_small_tcon_free_mid(req);
    return rc;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    struct TCP_Server_Info *server;

    if (!io_parms || !nbytes || !iov || n_vec <= 0) {
        return -EINVAL;
    }

    server = io_parms->cifs_sid;
    if (!server || server->tcpStatus != CifsGood) {
        return -ECONNREFUSED;
    }

    req = kmalloc(sizeof(*req) + iov[0].iov_len, GFP_KERNEL);
    if (!req) {
        return -ENOMEM;
    }

    resp = kmalloc(sizeof(*resp), GFP_KERNEL);
    if (!resp) {
        kfree(req);
        return -ENOMEM;
    }

    memset(req, 0, sizeof(*req) + iov[0].iov_len);
    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->DataLength = cpu_to_le32(iov[0].iov_len);
    memcpy(req->Data, iov[0].iov_base, iov[0].iov_len);

    rc = cifs_send_recv(io_parms, server, (char *)req, iov, n_vec, (char **)&resp);
    if (rc < 0) {
        goto out;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
out:
    kfree(req);
    kfree(resp);
    return rc;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
                      struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;

    req = cifs_buf_get();
    if (!req) {
        return -ENOMEM;
    }

    resp = cifs_buf_get();
    if (!resp) {
        cifs_buf_release(req);
        return -ENOMEM;
    }

    req->hdr.MessageID = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->pid;
    req->ByteOffset = cpu_to_le64(io_parms->offset);
    req->DataLength = cpu_to_le32(*nbytes);

    rc = cifs_send_recv(io_parms->tcon->ses->server, req, iov, n_vec,
                        CIFSWrite, &resp, 0);
    if (rc) {
        cifs_buf_release(req);
        cifs_buf_release(resp);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
    cifs_buf_release(req);
    cifs_buf_release(resp);
    return 0;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req = NULL;
    struct smb2_write_response *resp = NULL;
    struct cifs_tcon *tcon = io_parms->tcon;
    struct TCP_Server_Info *server = tcon->ses->server;

    if (!server || !server->smb_session) {
        return -ECONNRESET;
    }

    req = (struct smb2_write_request *)cifs_small_buf_get();
    if (!req) {
        return -ENOMEM;
    }

    resp = (struct smb2_write_response *)cifs_mid_alloc();
    if (!resp) {
        cifs_small_buf_put(req);
        return -ENOMEM;
    }

    req->hdr.MessageId = cpu_to_le64(++server->last_mid);
    req->hdr.SessionId = cpu_to_le64(io_parms->ses->Suid);
    req->hdr.TreeId = cpu_to_le64(io_parms->tcon->treeConnect);
    req->hdr.Channel = 0;
    req->hdr.CreditRequest = cpu_to_le16(1);
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(io_parms->length);
    req->FileId = io_parms->fid;
    req->Remaining = 0;

    rc = cifs_send_recv(xid, server, (char *)req, (char **)&resp, 0);
    if (rc != 0) {
        cifs_small_buf_put(req);
        cifs_mid_put(resp);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);

    cifs_small_buf_put(req);
    cifs_mid_put(resp);
    return 0;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec)
{
    int rc = 0;
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    struct TCP_Server_Info *server = io_parms->cfile->tcon->ses->server;

    if (!server || !serverCanDialect(server, SMB20))
        return -EOPNOTSUPP;

    req = smb2_init(SMB2_WRITE, server, sizeof(*req), (void **)&resp);
    if (!req)
        return -ENOMEM;

    req->FileId = io_parms->pid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(io_parms->length);
    req->PersistentFileId = io_parms->pfile_id;

    rc = cifs_send_recv(xid, server, (char *)req, iov, n_vec, CIFS_WRITE_OP, (char **)&resp);
    if (rc)
        goto out;

    *nbytes = le32_to_cpu(resp->DataLength);

out:
    kfree(req);
    return rc;
}
